per_case_results.actual_sql:
SELECT 
    (
        (
            (
                SELECT "overall_rating" FROM "Player" WHERE "player_name" = 'Ariel Borysiuk'
            )
            -
            (
                SELECT "overall_rating" FROM "Player" WHERE "player_name" = 'Paulin Puel'
            )
        )
        /
        (
            SELECT "overall_rating" FROM "Player" WHERE "player_name" = 'Paulin Puel'
        )
    ) * 100 AS "percentage_difference"
